#pragma once
#include <fstream>
#include <sstream>
static std::string trim(std::string s){auto a=s.find_first_not_of(" \t\r\n");if(a==s.npos)return {};return s.substr(a,s.find_last_not_of(" \t\r\n")-a+1);}
static std::string readBytes(const std::string&p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("Cannot read config.");return std::string(std::istreambuf_iterator<char>(f),{});}
static std::string keyName(int k){if(k>=112&&k<=135)return "F"+std::to_string(k-111);if(k>=65&&k<=90)return std::string(1,(char)k);if(k>=48&&k<=57)return std::string(1,(char)k);if(k>=96&&k<=105)return "NumPad"+std::to_string(k-96);switch(k){case 8:return "Backspace";case 9:return "Tab";case 13:return "Enter";case 19:return "Pause";case 20:return "CapsLock";case 27:return "Escape";case 32:return "Space";case 33:return "PageUp";case 34:return "PageDown";case 35:return "End";case 36:return "Home";case 37:return "Left";case 38:return "Up";case 39:return "Right";case 40:return "Down";case 44:return "PrintScreen";case 45:return "Insert";case 46:return "Delete";case 145:return "ScrollLock";case 192:return "Grave";}return {};}
static std::string encodeBinding(const Action&a,std::string input){input=trim(input);if(input.empty()||input.find_first_of("\r\n;=|")!=input.npos)throw std::runtime_error("Enter one key or combination, such as F6 or Ctrl+F6.");std::string original=read(a);auto bar=original.find('|');std::string base=trim(original.substr(0,bar));bool numeric=!base.empty()&&isdigit((unsigned char)base[0])&&base.find(',')==base.npos;std::string converted=input;
 if(numeric){if(input.find('+')!=input.npos)throw std::runtime_error("This setting stores a plain key code. Enter a single key; existing modifier flags are preserved.");int k=vk(input);if(k<8||k>254||k==16||k==17||k==18)throw std::runtime_error("Unsupported key.");if(base.size()>2&&base[0]=='0'&&(base[1]=='x'||base[1]=='X')){char b[16];snprintf(b,sizeof b,"0x%X",k);converted=b;}else converted=std::to_string(k);}
 else if(input.find('+')!=input.npos&&base.find('+')==base.npos)throw std::runtime_error("This binding has no demonstrated modifier syntax. Use a single key."); else if(lower(a.file)=="reshade.ini")throw std::runtime_error("Change ReShade shortcuts in its own settings; it rewrites this file.");
 if(bar!=original.npos)converted+=original.substr(bar);
 auto ks=keysFrom(a,converted);if(ks.empty()||ks.size()>4)throw std::runtime_error("Unsupported shortcut.");std::set<int> seen;for(int k:ks)if(k<8||k>254||!seen.insert(k).second)throw std::runtime_error("Unsupported or duplicate key.");if(ks.back()==16||ks.back()==17||ks.back()==18)throw std::runtime_error("Choose a main key after modifiers.");
 // Round-trip named syntax before saving; do not invent a format for unknown mods.
 if(!numeric){for(int k:ks)if(k!=16&&k!=17&&k!=18&&keyName(k).empty())throw std::runtime_error("Unsupported key name.");}
 return converted;}
static std::string replaceValue(const std::string&bytes,const Action&a,const std::string&value){if(bytes.size()>1024*1024||bytes.find('\0')!=bytes.npos)throw std::runtime_error("Config format unsupported by editor.");std::string result=bytes,section;size_t pos=0;int matches=0;size_t begin=0,finish=0;while(pos<bytes.size()){auto end=bytes.find('\n',pos);if(end==bytes.npos)end=bytes.size();std::string line=bytes.substr(pos,end-pos);if(pos==0&&line.substr(0,3)=="\xef\xbb\xbf")line.erase(0,3);auto text=trim(line);if(!text.empty()&&text[0]=='['){auto close=text.find(']');if(close!=text.npos)section=text.substr(1,close-1);}else if(lower(section)==lower(a.section)&&!text.empty()&&text[0]!=';'&&text[0]!='#'){auto eq=line.find('=');if(eq!=line.npos&&lower(trim(line.substr(0,eq)))==lower(a.key)){++matches;size_t start=eq+1;while(start<line.size()&&(line[start]==' '||line[start]=='\t'))++start;size_t stop=line.find(';',start);if(stop==line.npos)stop=line.size();while(stop>start&&(line[stop-1]==' '||line[stop-1]=='\t'||line[stop-1]=='\r'))--stop;begin=pos+start;finish=pos+stop;}}pos=end+1;}if(matches!=1)throw std::runtime_error("Missing or duplicate setting; edit the config manually.");result.replace(begin,finish-begin,value);return result;}
static void saveBinding(const Action&a,const std::string&expected,const std::string&value){auto path=std::filesystem::weakly_canonical(std::filesystem::path(folder)/a.file);auto root=std::filesystem::weakly_canonical(folder);auto relative=path.lexically_relative(root);if(relative.empty()||*relative.begin()==".."||!std::filesystem::is_regular_file(path))throw std::runtime_error("Config path is outside mod folder.");auto current=readBytes(path.string());if(current!=expected)throw std::runtime_error("Config changed since editing began. Select it again.");auto updated=replaceValue(current,a,value);auto backup=path.string()+".modactivator.bak";if(!std::filesystem::exists(backup)&&!CopyFileA(path.string().c_str(),backup.c_str(),TRUE))throw std::runtime_error("Could not create backup.");auto temporary=path.string()+".modactivator.tmp";HANDLE f=CreateFileA(temporary.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);if(f==INVALID_HANDLE_VALUE)throw std::runtime_error("Cannot create temporary config; check permissions or stale temp file.");DWORD written=0;bool ok=WriteFile(f,updated.data(),(DWORD)updated.size(),&written,nullptr)&&written==updated.size()&&FlushFileBuffers(f);CloseHandle(f);if(!ok){DeleteFileA(temporary.c_str());throw std::runtime_error("Config write failed.");}if(readBytes(path.string())!=expected){DeleteFileA(temporary.c_str());throw std::runtime_error("Config changed while saving.");}if(!ReplaceFileA(path.string().c_str(),temporary.c_str(),nullptr,0,nullptr,nullptr)){DeleteFileA(temporary.c_str());throw std::runtime_error("Could not replace config. Original preserved.");}WritePrivateProfileStringA(nullptr,nullptr,nullptr,path.string().c_str());}
static void drawHotkeys(){static Action editing;static bool selected=false;static char entry[128]="";static std::string snapshot,message;static bool acknowledge=false;static std::string lastInput,encodedCache,validationError;static std::vector<int> proposedCache;std::vector<Action> list;{std::lock_guard<std::mutex>lock(catalogMutex);list=allBindings;}
 ImGui::TextWrapped("Detected keyboard bindings for loaded mods. Red: exact conflict. Amber: same key, different modifiers. Restart after saving; mods may still use their old shortcuts until then.");
 if(!message.empty())ImGui::TextWrapped("%s",message.c_str());
 ImGui::BeginChild("Bindings",ImVec2(0,selected?280:420),true);
 for(size_t i=0;i<list.size();++i){auto&a=list[i];int severity=a.severity;const std::string& names=a.overlapNames;if(severity)ImGui::PushStyleColor(ImGuiCol_Text,severity==2?ImVec4(1,.3f,.3f,1):ImVec4(1,.75f,.2f,1));ImGui::PushID((int)i);if(ImGui::Selectable((a.label+" : "+a.cachedValue).c_str())){try{editing=a;snapshot=readBytes(folder+a.file);selected=true;entry[0]=0;lastInput="\x01";acknowledge=false;message.clear();}catch(const std::exception&e){message=e.what();}}if(severity&&ImGui::IsItemHovered())ImGui::SetTooltip("%s%s",severity==2?"Exact conflict\n":"Shared base key (possible conflict)\n",names.c_str());ImGui::PopID();if(severity)ImGui::PopStyleColor();}ImGui::EndChild();
 if(selected){ImGui::TextWrapped("Editing: %s",editing.label.c_str());if(ImGui::InputText("New shortcut",entry,sizeof entry))acknowledge=false;ImGui::TextWrapped("Numeric settings accept one key and keep modifier flags. Named settings accept combinations. Controller suffixes are preserved.");try{if(lastInput!=entry){lastInput=entry;validationError.clear();try{encodedCache=encodeBinding(editing,entry);proposedCache=keysFrom(editing,encodedCache);}catch(const std::exception&e){validationError=e.what();}}if(!validationError.empty())throw std::runtime_error(validationError);const auto& encoded=encodedCache;const auto& proposed=proposedCache;bool clashes=conflict(proposed,{17,16,8})!=0;for(auto&a:list)if(identity(a)!=identity(editing)&&conflict(proposed,a.cachedKeys)){clashes=true;ImGui::TextColored(ImVec4(1,.6f,.2f,1),"Overlaps: %s",a.label.c_str());}if(conflict(proposed,{17,16,8}))ImGui::TextWrapped("Overlaps ModActivator's Ctrl+Shift+Backspace.");if(clashes)ImGui::Checkbox("Save despite overlap",&acknowledge);ImGui::BeginDisabled(clashes&&!acknowledge);if(ImGui::Button("Save hotkey")){try{saveBinding(editing,snapshot,encoded);message="Saved with .modactivator.bak backup. Restart the game to apply.";selected=false;refreshRequested.store(true);}catch(const std::exception&e){message=e.what();}}ImGui::EndDisabled();}catch(const std::exception&e){if(entry[0])ImGui::TextWrapped("%s",e.what());}ImGui::SameLine();if(ImGui::Button("Cancel"))selected=false;}}


